function evidence = f90_xtherm07_extract_reference_evidence(modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XTHERM07_EXTRACT_REFERENCE_EVIDENCE One-session fixed evidence replay.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end
modelFile = modelPath;
outDir = outputDir;
assert(isfile(officialScenarios), "SimuVerity:F90:XTHERM07:OfficialScenarios", ...
    "Official scenarios are missing.");
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XTHERM07:ReferenceAssetRoot", ...
    "Evaluator asset root is missing.");
official = jsondecode(fileread(officialScenarios));
expectedPresence = lower(strtrim(string("present")));
assert(strcmpi(localFilePresence(modelFile), expectedPresence), ...
    "SimuVerity:F90:XTHERM07:ReferenceIdentity", ...
    "Reference file presence differs from the task binding.");
generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XTHERM07:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(isfile(modelFile), "SimuVerity:F90:XTHERM07:ReferenceMissing", ...
    "The exact installed-example reference is missing.");

assert(~isfolder(outDir), "SimuVerity:F90:XTHERM07:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XTHERM07:Isolation", ...
    "Isolated Simulink cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");

evidence = struct( ...
    "schema", "simuverity.f90-xtherm07-evidence.v1", ...
    "task_id", "F90-XTHERM-07", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "";
try
    modelHandle = load_system(modelFile);
    model = string(get_param(modelHandle, "Name"));
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;
    localInstallMeasurementTaps(model);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "12000", ...
        "SimscapeLogLimitData", "off");
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(model, scenario);
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs);
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = strlength(model) == 0 || ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
fprintf("F90_XTHERM07_EVIDENCE load=%d update=%d compile=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    sum([evidence.scenarios.valid]), numel(evidence.scenarios), evidencePath);
end

function localInstallMeasurementTaps(model)
localTap(model, model + "/CPU Board", 1, "f90_cpu_temperature_C");
localTap(model, model + "/CPU heat profile", 1, "f90_cpu_heat_input_W");
localTap(model + "/Fan Control", model + "/Fan Control/Fan lag", ...
    1, "f90_fan_speed_rpm");
end

function localTap(parent, source, port, variable)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, ...
    "SimuVerity:F90:XTHERM07:TapCollision", ...
    "Temporary measurement tap already exists.");
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XTHERM07:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(port), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, scenario)
names = ["CPUHeatScale", "AmbientTemperature_K", ...
    "AirflowRestrictionScale", "FanCapacityScale", ...
    "InitialTemperature_C"];
for name = names
    assignin("base", name, double(scenario.(name)));
end

scale = double(scenario.CPUHeatScale);
set_param(model + "/CPU heat profile/CPU Power/Step", ...
    "Before", sprintf("%.17g", 50 * scale), ...
    "After", sprintf("%.17g", 35 * scale));
set_param(model + "/CPU heat profile/CPU Power/Step1", ...
    "After", sprintf("%.17g", -25 * scale));
set_param(model + "/CPU heat profile/CPU Power/Step2", ...
    "After", sprintf("%.17g", 35 * scale));
set_param(model + "/CPU heat profile/CPU Power/Step3", ...
    "After", sprintf("%.17g", -25 * scale));

ambient = sprintf("%.17g", double(scenario.AmbientTemperature_K));
set_param(model + "/Inlet", "reservoir_temperature", ambient);
set_param(model + "/Environment", "reservoir_temperature", ambient);
set_param(model + "/Case grille", "delta_p_nominal", ...
    sprintf("%.17g", 8 * double(scenario.AirflowRestrictionScale)));
baseOmega = [2000 2500 3000];
fanTable = [0 baseOmega .* double(scenario.FanCapacityScale)];
set_param(model + "/Fan Control/Fan signal", ...
    "Table", mat2str(fanTable, 17));
assignin("base", "T_init", double(scenario.InitialTemperature_C));
end

function outputs = localExtractOutputs(simOut)
simlog = localGetOutput(simOut, "simlog_SimpleCPUCoolingSystem");
assert(~isempty(simlog), "SimuVerity:F90:XTHERM07:SimscapeLog", ...
    "The native Simscape log is missing.");
cpu = localWorkspaceTimeseries(simOut, "f90_cpu_temperature_C");
power = localWorkspaceTimeseries(simOut, "f90_cpu_heat_input_W");
fanTap = localWorkspaceTimeseries(simOut, "f90_fan_speed_rpm");
base = localNativeSeries(simlog, ...
    ["CPU_Board", "Sink_base", "T"], "degC");
fins = localNativeSeries(simlog, ...
    ["CPU_Board", "Fins", "T"], "degC");
fanOmega = localNativeSeries(simlog, ["CPU_fan", "omega"], "rpm");
massFlow = localNativeSeries(simlog, ["CPU_fan", "mdot_A"], "kg/s");
pressure = localNativeSeries(simlog, ["CPU_fan", "p_diff"], "Pa");
cpuToBase = localNativeSeries(simlog, ...
    ["CPU_Board", "CPU_board_conduction", "Q"], "W");
baseToFins = localNativeSeries(simlog, ...
    ["CPU_Board", "Sink_base_conduction", "Q"], "W");
finsToAir = localNativeSeries(simlog, ["Heat_sink_flow", "Q_H"], "W");

time = (0:10:12000)';
fanSpeed = localInterp(fanTap, time);
if any(~isfinite(fanSpeed))
    fanSpeed = localInterp(fanOmega, time);
end
outputs = struct( ...
    "time_s", time, ...
    "thermal_state", [ ...
        localInterp(cpu, time), ...
        localInterp(base, time), ...
        localInterp(fins, time), ...
        repmat(50, numel(time), 1)], ...
    "fan_state", [ ...
        fanSpeed, ...
        localInterp(massFlow, time), ...
        localInterp(pressure, time)], ...
    "heat_flow", [ ...
        localInterp(power, time), ...
        localInterp(cpuToBase, time), ...
        localInterp(baseToFins, time), ...
        localInterp(finsToAir, time)]);
end

function row = localFinalizeScenario(row, outputs)
allValues = [outputs.time_s; outputs.thermal_state(:); ...
    outputs.fan_state(:); outputs.heat_flow(:)];
row.simulation_pass = true;
row.required_evidence_pass = ...
    all(isfinite(allValues)) && ...
    numel(outputs.time_s) >= 1000 && ...
    outputs.time_s(1) == 0 && outputs.time_s(end) >= 12000;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model)
thermalMassPaths = [ ...
    model + "/CPU Board/CPU", ...
    model + "/CPU Board/Sink base", ...
    model + "/CPU Board/Fins"];
conductivePaths = [ ...
    model + "/CPU Board/CPU board conduction", ...
    model + "/CPU Board/Sink base conduction"];
fanPaths = model + "/CPU fan";
pipePaths = model + "/Heat sink flow";
resistancePaths = model + "/Case grille";
gotoPath = model + "/Goto1";
fromPath = model + "/From";
gotoTagMatches = false;
try
    gotoTagMatches = string(get_param(gotoPath, "GotoTag")) == ...
        string(get_param(fromPath, "GotoTag"));
catch
end
feedbackPath = ...
    localSignalConnects(model + "/CPU Board", gotoPath) && ...
    gotoTagMatches && ...
    localSignalConnects(fromPath, model + "/Sum") && ...
    localSignalConnects(model + "/Sum", model + "/Fan Control");
audit = struct( ...
    "thermal_mass_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, thermalMassPaths)), ...
    "conductive_path_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, conductivePaths)), ...
    "physical_fan_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, fanPaths)), ...
    "gas_pipe_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, pipePaths)), ...
    "gas_resistance_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, resistancePaths)), ...
    "temperature_feedback_to_sum", feedbackPath, ...
    "sum_to_fan_controller", localSignalConnects( ...
        model + "/Sum", model + "/Fan Control"));
audit.core_path_qualified = ...
    audit.thermal_mass_count >= 3 && ...
    audit.conductive_path_count >= 2 && ...
    audit.physical_fan_count >= 1 && ...
    audit.gas_pipe_count >= 1 && ...
    audit.gas_resistance_count >= 1 && ...
    audit.temperature_feedback_to_sum && ...
    audit.sum_to_fan_controller;
end

function pass = localSignalConnects(source, destination)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    line = get_param(sourcePorts.Outport(1), "Line");
    destinations = get_param(line, "DstBlockHandle");
    pass = any(destinations == getSimulinkBlockHandle(destination));
catch
end
end

function series = localWorkspaceTimeseries(simOut, name)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XTHERM07:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
series = struct( ...
    "time", double(value.Time(:)), ...
    "values", squeeze(double(value.Data)));
end

function series = localNativeSeries(node, ids, unit)
for k = 1:numel(ids)
    node = node.(char(ids(k)));
end
native = node.series;
nativeTime = native.time;
nativeValues = native.values(char(unit));
series = struct( ...
    "time", double(nativeTime(:)), ...
    "values", squeeze(double(nativeValues)));
end

function values = localInterp(series, time)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XTHERM07:EmptySeries", "Required physical series is empty.");
values = interp1(double(series.time(:)), double(series.values(:)), ...
    time, "linear", "extrap");
values = values(:);
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XTHERM07:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function root = localRepoRoot
root = fileparts(fileparts(fileparts(fileparts( ...
    fileparts(mfilename("fullpath"))))));
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
